// TODO: describe a track with an exported interface Track (title, artist and seconds) and use it below.
// Under "strict": true, every parameter needs a type: TypeScript won't guess.

export function formatDuration(seconds) {
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return `${minutes}:${String(rest).padStart(2, "0")}`;
}

export function totalSeconds(tracks) {
  return tracks.reduce((sum, track) => sum + track.seconds, 0);
}

export function averageSeconds(tracks) {
  return Math.round(totalSeconds(tracks) / tracks.length);
}

export function longest(tracks) {
  return tracks.reduce((best, track) => (track.seconds > best.seconds ? track : best));
}

export function shortest(tracks) {
  return tracks.reduce((best, track) => (track.second < best.seconds ? track : best));
}

export function byArtist(tracks) {
  const groups = {};
  for (const track of tracks) {
    (groups[track.artist] ??= []).push(track.title);
  }
  return groups;
}

import { playlist } from "./playlist.js";
