app.use(express.json());

const tasks = [{ id: 1, title: "Write the API", done: false }];

app.get("/api/tasks", (req, res) => {
  res.json(tasks);
});

app.post("/api/tasks", (req, res) => {
  const title = typeof req.body?.title === "string" ? req.body.title.trim() : "";
  if (!title) {
    res.status(400).json({ error: "A task needs a title" });
    return;
  }
  const task = { id: tasks.length + 1, title, done: false };
  tasks.push(task);
  res.status(201).json(task);
});

app.listen(3000, () => console.log("Listening on http://localhost:3000"));

export function validateTitle(input: unknown): string {
  const title = typeof input === "string" ? input.trim() : "";
  if (!title) {
    throw new Error("A task needs a title");
  }
  if (title.length > 80) {
    throw new Error("A title can have at most 80 characters");
  }
  return title;
}

