describe("validateTitle", () => {
  it("trims the title", () => {
    expect(validateTitle("  Write tests  ")).toBe("Write tests");
  });

  it("rejects a missing title", () => {
    expect(() => validateTitle(undefined)).toThrow("A task needs a title");
  });
});

