export interface Task {
  id: number;
  title: string;
  done: boolean;
}

/** Thrown for input that breaks a rule; the server turns it into 400 Bad Request. */
export class ValidationError extends Error {}

/** Keeps tasks in memory. A new TaskList starts empty. */
export class TaskList {
  private tasks: Task[] = [];
  private nextId = 1;

  all(): Task[] {
    return [...this.tasks];
  }

  // TODO 1: add(title: unknown): Task
  //   The title must be a string that isn't blank once trimmed: otherwise
  //   throw new ValidationError("A task needs a title").
  //   It can have at most 80 characters: otherwise
  //   throw new ValidationError("A title can have at most 80 characters").
  //   Store the trimmed title with the next id and done: false, and return the new task.

  // TODO 2: complete(id: number): Task | undefined
  //   Mark the task done and return it, or return undefined if there's no task with that id.
}

import { beforeEach, describe, expect, it } from "vitest";
import { TaskList, ValidationError } from "./tasks.js";

describe("TaskList", () => {
  let list: TaskList;

  beforeEach(() => {
    list = new TaskList();
  });

  it("starts empty", () => {
    expect(list.all()).toEqual([]);
  });

  it("adds a task with the next id and a trimmed title", () => {
    list.add("First task");
    expect(list.add("  Write tests  ")).toEqual({ id: 2, title: "Write tests", done: false });
  });

  it("rejects a blank title", () => {
    expect(() => list.add("   ")).toThrow(ValidationError);
  });

  // TODO: three more tests
  // - a title that isn't a string, such as 42, throws ValidationError
  // - a title of 81 characters throws ValidationError, but one of exactly 80 ("x".repeat(80)) is accepted
  // - complete(1) marks the first task done and returns it, and complete(99) returns undefined
});

